INSERT INTO repositories (ghr_id, full_name, description, primary_language, license_spdx, topics_json, repo_created_at, stars_total, forks_total, stars_delta_6h, stars_delta_24h, stars_delta_7d, lifecycle_state, is_curated, curated_issue, curated_category, first_seen_at, last_seen_in_trending_at, last_updated_at, last_notified_at, last_notified_state, last_curated_notified_at, surging_entered_at) VALUES (1380797051, 'lhlGitHub/threejs-architecture-effects', '让 AI 生成逐层搭建的 3D 古建筑。这是一个适用于 Codex、Claude Code 和 Cursor 的 AI 技能，可生成基于 Three.js 的 3D 中式古建网站。建筑会按照砖墙、木构架、斗拱和飞檐的顺序逐步搭建，砖、木、瓦、石等材质均由代码生成，支持拖动时间轴回放搭建过程、旋转缩放视角和查看飞檐特写等功能。', 'TypeScript', 'MIT', '[]', '2026-09-22T03:01:05Z', 707, 73, 0, 0, 0, 'DISCOVERY', 1, 'vol-126', 'Skills', '2026-11-06T18:38:52.282880Z', '2026-11-06T18:38:52.282880Z', '2026-11-07T12:32:38.104745Z', NULL, NULL, NULL, NULL);
